public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];
    Arrays.fill(visited, false);

    // Create a Queue to store the n-tersections to be visited
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(start[0]);

    while (!queue.isEmpty()) {
        // Dequeue an n-tersection
        int current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (current == end[0]) {
            return "can be travelled";
        }

        // If the current n-tersection has not been visited, mark it as visited and add its neighbors to the queue
        if (!visited[current]) {
            visited[current] = true;
            for (int[] path : paths) {
                if (path[0] == current) {
                    queue.offer(path[1]);
                } else if (path[1] == current) {
                    queue.offer(path[0]);
                }
            }
        }
    }

    // If the queue is empty and the ending n-tersection has not been reached, return "cannot be travelled"
    return "cannot be travelled";
}
